// unmarshalCreateTransactionPayloadRequestBodyToFinanceCreateTransactionPayload
// builds a value of type *finance.CreateTransactionPayload from a value of
// type *CreateTransactionPayloadRequestBody.
func unmarshalCreateTransactionPayloadRequestBodyToFinanceCreateTransactionPayload(v *CreateTransactionPayloadRequestBody) *finance.CreateTransactionPayload {
	res := &finance.CreateTransactionPayload{
		EntityID:          v.EntityID,
		TransactionNumber: v.TransactionNumber,
		TransactionType:   *v.TransactionType,
		TransactionDate:   *v.TransactionDate,
		Description:       *v.Description,
		ReferenceNumber:   v.ReferenceNumber,
	}
	if v.CurrencyCode != nil {
		res.CurrencyCode = *v.CurrencyCode
	}
	if v.CurrencyCode == nil {
		res.CurrencyCode = "USD"
	}
	res.Entries = make([]*finance.TransactionEntryPayload, len(v.Entries))
	for i, val := range v.Entries {
		res.Entries[i] = unmarshalTransactionEntryPayloadRequestBodyToFinanceTransactionEntryPayload(val)
	}

	return res
}

